// Окружение: PROD app.techory.ai, сессия gps (Nikita Test, компания «בדיקה»), интерфейс EN.
// Разметка сверена 12.11.2026 по живой странице (только просмотр): /gpsworkflow — вкладки New/All (role=tab) в
// complementary, сообщения — кнопки в list; клик открывает dialog с именем отправителя, статусом и кнопками
// Open job / Create invoice / Open invoice. Тесты только читают существующие данные (новое сообщение = входящее SMS).
import { expect, Locator, Page } from '@playwright/test';

export const ROLE = 'gps';
export const GPS_COMPANY_ID = 'd70f1465-b456-4cc7-b582-5223a493e3f7'; // «בדיקה»
export const COMPANY_NUMBER = '(507) 568-6036';

/** EN-интерфейс и компания «בדיקה» до загрузки страницы. */
export async function prepare(page: Page) {
  await page.addInitScript((company) => {
    try {
      window.localStorage.setItem('preferred-language', 'en');
      window.localStorage.setItem('selected-company-id', company);
    } catch { /* ignore */ }
  }, GPS_COMPANY_ID);
}

/** GPS Workflow → вкладка All. Проверяет, что это компания с номером (507) 568-6036. */
export async function openGpsAll(page: Page) {
  await page.goto('/gpsworkflow');
  await expect(page.getByRole('heading', { name: 'GPS Workflow', level: 1 })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(`Your company number: ${COMPANY_NUMBER}`)).toBeVisible();
  await page.getByRole('tab', { name: 'All' }).click();
  await expect(page.getByRole('tab', { name: 'All' })).toHaveAttribute('aria-selected', 'true');
  return messageList(page);
}

export function messageList(page: Page): Locator {
  return page.getByRole('complementary').getByRole('list');
}

/** Кнопка сообщения в списке All по началу названия (имя отправителя … время … статус … адрес). */
export function messageItem(page: Page, name: RegExp): Locator {
  return messageList(page).getByRole('button', { name }).first();
}

/** Открыть сообщение и вернуть его панель (dialog). */
export async function openMessage(page: Page, name: RegExp): Promise<Locator> {
  const item = messageItem(page, name);
  await expect(item, `сообщение ${name} есть в списке All`).toBeVisible({ timeout: 30_000 });
  await item.click();
  const dialog = page.getByRole('dialog');
  await expect(dialog).toBeVisible();
  await expect(dialog.getByRole('button', { name: 'Open job' })).toBeVisible({ timeout: 20_000 });
  return dialog;
}

/** Open job из панели → id работы из адреса JobDetail?id=… */
export async function openJobFromDialog(page: Page, dialog: Locator): Promise<string> {
  await dialog.getByRole('button', { name: 'Open job' }).click();
  await page.waitForURL(/\/JobDetail\?id=/i, { timeout: 30_000 });
  const id = new URL(page.url()).searchParams.get('id');
  expect(id, 'id работы в адресе').toBeTruthy();
  return id as string;
}
